import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Swal from "sweetalert2";

export default function Scans() {
  const navigate = useNavigate();
  const [scans, setScans] = useState([]);

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("scans") || "[]");
    setScans(saved);
  }, []);

  const handleDelete = (id) => {
    Swal.fire({
      title: "¿Eliminar escaneo?",
      text: "Esta acción no se puede deshacer.",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#e24b4a",
      cancelButtonColor: "#9ca3af",
      confirmButtonText: "Sí, eliminar",
      cancelButtonText: "Cancelar",
      background: "#f5f2ec",
      customClass: { popup: "rounded-3xl" },
    }).then((result) => {
      if (result.isConfirmed) {
        const updated = scans.filter((s) => s.id !== id);
        setScans(updated);
        localStorage.setItem("scans", JSON.stringify(updated));
        Swal.fire({
          title: "Eliminado",
          icon: "success",
          timer: 1200,
          showConfirmButton: false,
          background: "#f5f2ec",
          customClass: { popup: "rounded-3xl" },
        });
      }
    });
  };

  const riskConfig = {
    Alto: { badge: "bg-red-50 text-red-600", dot: "bg-red-500" },
    Medio: { badge: "bg-amber-50 text-amber-700", dot: "bg-amber-500" },
    Bajo: { badge: "bg-green-50 text-green-700", dot: "bg-green-500" },
    Ninguno: { badge: "bg-green-50 text-green-700", dot: "bg-green-500" },
  };

  return (
    <div className="min-h-screen bg-[#f4f7f1] flex flex-col">

      {/* NAVBAR */}
      <header className="bg-white border-b border-gray-100 px-4 sm:px-6 py-3 flex items-center gap-3 sticky top-0 z-20 shadow-sm">
        <button
          onClick={() => navigate("/home")}
          className="w-9 h-9 rounded-full bg-gray-100 flex items-center justify-center hover:bg-gray-200 transition shrink-0"
        >
          ←
        </button>
        <div className="flex items-center gap-2 flex-1 min-w-0">
          <div className="w-8 h-8 rounded-lg bg-green-700 flex items-center justify-center text-white text-sm shrink-0">
            🌿
          </div>
          <div className="min-w-0">
            <h1 className="font-bold text-sm leading-tight">Mis escaneos</h1>
            <p className="text-xs text-gray-500 hidden sm:block">
              {scans.length} escaneo{scans.length !== 1 ? "s" : ""} registrado{scans.length !== 1 ? "s" : ""}
            </p>
          </div>
        </div>
        <button
          onClick={() => navigate("/scan")}
          className="flex items-center gap-1.5 bg-green-700 text-white px-3 py-1.5 rounded-xl text-xs font-semibold hover:bg-green-800 transition shrink-0"
        >
          📷 Nuevo
        </button>
      </header>

      <main className="flex-1 max-w-4xl mx-auto w-full px-4 sm:px-6 py-6">

        {scans.length === 0 ? (
          <div className="bg-white rounded-3xl p-10 flex flex-col items-center justify-center gap-4 text-center">
            <span className="text-6xl">🍃</span>
            <h2 className="font-bold text-lg text-gray-800">No tienes escaneos aún</h2>
            <p className="text-sm text-gray-500 max-w-xs">
              Toma una foto de una hoja de banano para detectar si tiene Sigatoka negra.
            </p>
            <button
              onClick={() => navigate("/scan")}
              className="bg-green-700 hover:bg-green-800 transition text-white px-6 py-3 rounded-2xl text-sm font-semibold"
            >
              📷 Hacer mi primer escaneo
            </button>
          </div>
        ) : (
          <div className="space-y-3">
            {scans.map((item) => {
              const risk = riskConfig[item.nivel_riesgo] || riskConfig["Medio"];
              return (
                <div
                  key={item.id}
                  className="bg-white rounded-2xl border border-gray-100 overflow-hidden flex hover:shadow-sm transition"
                >
                  {/* Clic en la tarjeta va al resultado */}
                  <button
                    onClick={() =>
                      navigate("/result", {
                        state: {
                          result: null,
                          imageUrl: item.imageUrl,
                          scanId: item.id,
                        },
                      })
                    }
                    className="flex items-center gap-4 flex-1 p-3 sm:p-4 text-left"
                  >
                    {item.imageUrl ? (
                      <img
                        src={item.imageUrl}
                        alt={item.enfermedad}
                        className="w-16 h-16 sm:w-20 sm:h-20 rounded-xl object-cover shrink-0"
                      />
                    ) : (
                      <div className="w-16 h-16 sm:w-20 sm:h-20 rounded-xl bg-green-50 flex items-center justify-center text-2xl shrink-0">
                        🍃
                      </div>
                    )}

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap mb-1">
                        <span className={`w-2 h-2 rounded-full shrink-0 ${risk.dot}`} />
                        <h3 className="font-semibold text-sm sm:text-base text-gray-800 truncate">
                          {item.enfermedad}
                        </h3>
                        <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${risk.badge}`}>
                          {item.nivel_riesgo}
                        </span>
                      </div>
                      <p className="text-xs text-gray-500 truncate">
                        {item.planta} · {item.fecha}
                      </p>
                      <p className="text-xs text-gray-400 mt-0.5">
                        Confianza: {item.confianza}%
                      </p>
                    </div>

                    <span className="text-gray-300 text-lg shrink-0">›</span>
                  </button>

                  {/* Botón eliminar */}
                  <button
                    onClick={() => handleDelete(item.id)}
                    className="border-l border-gray-100 px-4 text-gray-300 hover:text-red-500 hover:bg-red-50 transition flex items-center justify-center shrink-0"
                    title="Eliminar"
                  >
                    🗑️
                  </button>
                </div>
              );
            })}
          </div>
        )}
      </main>
    </div>
  );
}
